1	/* ===== Dù lượn và đi dạo nhiều người: máy trạng thái phiên (không DOM, không three) =====
2	   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo. Hai nhóm 5 slot riêng; peers là nhóm cùng loại với mình
3	   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho cả hai loại (đi dạo cũng vậy). */
4	import type { Flyer, Kind, ServerMsg } from './protocol';
5	import type { Transport } from './client';
6	import { multiParams } from './params';
7	
8	export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
9	export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';
10	
11	export class MultiSession {
12	  phase: Phase = 'connecting';
13	  flyers: Flyer[] = [];
14	  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
15	  mySlot = -1;
16	  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
17	  invite = false;     // đang xem và còn chỗ trống
18	  notice: Notice = '';
19	  name = '';
20	  onChange: () => void = () => {};
21	  onPos: (f: number[][]) => void = () => {};
22	  onWalkPos: (w: number[][]) => void = () => {};
23	  private t: Transport | null = null;
24	  private disposed = false;
25	  private first = true; // chưa nhận lobby nào
26	
27	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}
28	
29	  /* Danh sách cùng loại với mình */
30	  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.flyers; }
31	
32	  open(): void {
33	    this.connect().then(t => {
34	      if (this.disposed) { t.close(); return; }
35	      this.t = t;
36	      t.onMessage = m => this.recv(m);
37	      t.onClose = () => this.lost();
38	    }, () => {
39	      if (this.disposed) return;
40	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
41	    });
42	  }
43	
44	  join(name: string): void {
45	    this.name = name; this.notice = '';
46	    this.t?.send(this.kind === 'walk' ? { t: 'join', name, kind: 'walk' } : { t: 'join', name });
47	  }
48	
49	  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
50	  leave(): void {
51	    if (this.phase !== 'flying') return;
52	    this.t?.send({ t: 'leave' });
53	    this.notice = 'released'; this.toWatching();
54	    this.onChange();
55	  }
56	
57	  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
58	  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
59	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
60	  }
61	
62	  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
63	  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
64	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
65	  }
66	
67	  heartbeat(): void {
68	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
69	  }
70	
71	  dispose(): void {
72	    this.disposed = true;
73	    this.t?.close(); this.t = null;
74	  }
75	
76	  private toWatching(): void {
77	    this.phase = 'watching'; this.mySlot = -1;
78	    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
79	    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
80	    this.fixWatched();
81	  }
82	  private mySlotWas = -1;
83	
84	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
85	  private fixWatched(): void {
86	    const ids = this.peers.map(f => f.slot);
87	    if (this.phase === 'watching') {
88	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
89	      this.invite = ids.length < (this.kind === 'walk' ? multiParams.stroll.slots : multiParams.slots);
90	    } else { this.watched = -1; this.invite = false; }
91	  }
92	
93	  private lost(): void {
94	    if (this.disposed) return;
95	    this.phase = 'solo'; this.notice = 'lost';
96	    this.flyers = []; this.walkers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
97	    this.t = null; this.onChange();
98	  }
99	
100	  /* Máy chủ cũ (lobby đầu không có walkers) không biết chỗ đi dạo: đóng kết nối, đi một mình như khi không kết nối được */
101	  private offline(): void {
102	    const t = this.t;
103	    this.t = null;
104	    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
105	    this.phase = 'solo'; this.notice = 'offline';
106	    this.flyers = []; this.walkers = [];
107	    this.onChange();
108	  }
109	
110	  private recv(m: ServerMsg): void {
111	    if (this.disposed) return;
112	    switch (m.t) {
113	      case 'lobby':
114	        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
115	        this.flyers = m.flyers;
116	        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
117	        if (this.first) {
118	          this.first = false;
119	          if (this.peers.length >= (this.kind === 'walk' ? multiParams.stroll.slots : multiParams.slots)) this.phase = 'watching';
120	          else this.phase = 'lobby';
121	        }
122	        // đang giữ chỗ: danh sách chỉ để hiển thị
123	        this.fixWatched();
124	        break;
125	      case 'joined':
126	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
127	        this.fixWatched();
128	        break;
129	      case 'rejected':
130	        if (m.why === 'name') this.notice = 'nameBad';
131	        else {
132	          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
133	          this.phase = 'watching';
134	          this.fixWatched();
135	        }
136	        break;
137	      case 'pos':
138	        this.onPos(m.f);
139	        if (Array.isArray(m.w)) this.onWalkPos(m.w);
140	        return;
141	      case 'released':
142	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
143	        break;
144	    }
145	    this.onChange();
146	  }
147	}
