1	/* ===== Test tích hợp Worker dù lượn nhiều người: spawn `wrangler dev`, kiểm join/đầy/lobby/Origin ===== */
2	import { spawn } from 'node:child_process';
3	import http from 'node:http';
4	
5	const PORT = 8799;
6	const HOST = `127.0.0.1:${PORT}`;
7	const ORIGIN = 'https://danangbridges.netlify.app';
8	const dir = new URL('../../server/multi/', import.meta.url);
9	
10	const wr = spawn(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['wrangler', 'dev', '--port', String(PORT)], { cwd: dir, shell: process.platform === 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
11	let log = '';
12	wr.stdout.on('data', d => { log += d; }); wr.stderr.on('data', d => { log += d; });
13	const stop = () => { try { if (process.platform === 'win32') spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); else wr.kill(); } catch {} };
14	process.on('exit', stop);
15	
16	let fails = 0;
17	const ok = (c, m) => { console.log((c ? 'ĐẠT ' : 'LỖI ') + m); if (!c) fails++; };
18	const sleep = ms => new Promise(r => setTimeout(r, ms));
19	
20	// Gửi yêu cầu nâng cấp WebSocket thô, trả mã HTTP
21	function upgradeStatus(origin) {
22	  return new Promise(res => {
23	    const headers = { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': 'REDACTED' };
24	    if (origin) headers.Origin = origin;
25	    const req = http.request({ host: '127.0.0.1', port: PORT, path: '/sky', headers });
26	    req.on('response', r => { res(r.statusCode); r.resume(); });
27	    req.on('upgrade', (r, sock) => { res(r.statusCode); sock.destroy(); });
28	    req.on('error', () => res(0));
29	    req.end();
30	  });
31	}
32	
33	function client() {
34	  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: ORIGIN } });
35	  const msgs = [];
36	  ws.onmessage = e => msgs.push(JSON.parse(e.data));
37	  const opened = new Promise((r, j) => { ws.onopen = r; ws.onerror = () => j(new Error('ws error')); });
38	  return { ws, msgs, opened, send: o => ws.send(JSON.stringify(o)) };
39	}
40	const last = (c, t) => [...c.msgs].reverse().find(m => m.t === t);
41	
42	try {
43	  for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
44	  ok(/Ready on/.test(log), 'wrangler dev sẵn sàng');
45	
46	  const cs = [];
47	  for (let i = 0; i < 6; i++) { const c = client(); await c.opened; cs.push(c); }
48	  await sleep(300);
49	  ok(cs.every(c => c.msgs[0] && c.msgs[0].t === 'lobby'), 'mỗi kết nối nhận lobby ngay khi vào');
50	  cs.forEach((c, i) => c.send({ t: 'join', name: 'P' + i }));
51	  await sleep(1000);
52	  const joined = cs.filter(c => last(c, 'joined')).length;
53	  const full = cs.filter(c => (last(c, 'rejected') || {}).why === 'full').length;
54	  ok(joined === 5 && full === 1, `6 kết nối join: ${joined} joined, ${full} rejected full`);
55	
56	  const gone = cs.find(c => last(c, 'joined'));
57	  const stay = cs.find(c => c !== gone && last(c, 'joined'));
58	  gone.ws.close();
59	  await sleep(1000);
60	  const lob = last(stay, 'lobby');
61	  ok(lob && lob.flyers.length === 4, `đóng một kết nối: lobby còn ${lob ? lob.flyers.length : '?'} tên`);
62	
63	  // Nhóm đi dạo: sau khi mọi người bay rời đi, một kết nối join kind 'walk' nhận joined kind walk, lobby có walkers 1 / flyers 0
64	  cs.forEach(c => { try { c.ws.close(); } catch {} });
65	  await sleep(1000);
66	  const wk = client(); await wk.opened;
67	  await sleep(300);
68	  wk.send({ t: 'join', name: 'Di', kind: 'walk' });
69	  await sleep(800);
70	  const wj = last(wk, 'joined'), wl = last(wk, 'lobby');
71	  ok(wj && wj.kind === 'walk' && wj.slot === 0, 'join kind walk nhận joined kind walk slot 0');
72	  ok(wl && wl.walkers && wl.walkers.length === 1 && wl.flyers.length === 0, `lobby sau đó: walkers ${wl && wl.walkers ? wl.walkers.length : '?'}, flyers ${wl ? wl.flyers.length : '?'}`);
73	  wk.send({ t: 'pos', x: 9999, y: 3, z: 0, yaw: 0, pose: 2, ts: 5 });
74	  await sleep(500);
75	  const wp = last(wk, 'pos');
76	  ok(wp && Array.isArray(wp.f) && wp.w && wp.w[0][1] === 400 && wp.w[0][5] === 2, 'pos đi dạo: f mảng, w kẹp x = 400, pose 2');
77	  wk.ws.close();
78	
79	  ok(await upgradeStatus('https://evil.example') === 403, 'Origin lạ -> 403');
80	  ok(await upgradeStatus(null) === 403, 'không có Origin -> 403');
