  assert.equal(r.hasFlyers(), true);
  r.disconnect('d2');
  assert.equal(r.hasFlyers(), false);
});

test('khôi phục sau hibernation giữ slot lái; kind lạ hoặc slot ngoài khoảng bị bỏ', () => {
