  assert.equal(o.length, 1); assert.equal(o[0].to, 'all');
  const m = o[0].msg as any;
  assert.deepEqual(m.f, [], 'f luôn có (khách cũ đọc m.f)'); assert.equal(m.w, undefined);
  assert.deepEqual(m.d, [[0, 10, 2.6, 0, 1, 5, -0.2, 777]]);
