  // người bay mới với máy chủ main vẫn bay bình thường
  assert.equal(flyer.phase, 'lobby'); flyer.join('Bay'); await tick();
  assert.equal(flyer.phase, 'flying'); assert.deepEqual(flyer.flyers, [{ slot: 0, name: 'Bay' }]);
});

