  assert.deepEqual(oldFly.flyers, [{ slot: 0, name: 'Bay' }]); assert.deepEqual(oldFly.walkers, [{ slot: 0, name: 'Di' }]);
  assert.deepEqual(oldWalk.walkers, [{ slot: 0, name: 'Di' }]); assert.deepEqual(oldWalk.peers, [{ slot: 0, name: 'Di' }]);
